using UnityHps;using System.IO.Compression;using System.Diagnostics;using System.Text.Json;
static PriorityQueue<(int Index,double Distance),double> Reference(double[][] points,double[] query,int count){var nearest=new PriorityQueue<(int Index,double Distance),double>();for(int i=0;i<points.Length;i++){double d=0;for(int j=0;j<5;j++){double v=points[i][j]-query[j];d+=v*v;}if(nearest.Count<count)nearest.Enqueue((i,d),-d);else if(d<nearest.Peek().Distance){nearest.Dequeue();nearest.Enqueue((i,d),-d);}}return nearest;}
static void Verify(double[][] p,double[] q,int k){var a=Reference(p,q,k).UnorderedItems.ToArray();var b=ResidualNeighborLookup.Find(p,q,k).UnorderedItems.ToArray();if(!a.SequenceEqual(b))throw new InvalidOperationException($"Heap mismatch rows={p.Length}, count={k}");}
if(args.Length!=2)throw new ArgumentException("Expected calibration resource path and result JSON path.");
var random=new Random(61203);int cases=0;
foreach(int rows in new[]{127,2049,4097,16385}){
 var points=Enumerable.Range(0,rows).Select(i=>Enumerable.Range(0,16).Select(j=>j<5?random.NextDouble()*2-1:123d+i+j).ToArray()).ToArray();var snapshot=points.Select(p=>(double[])p.Clone()).ToArray();
 foreach(int k in new[]{1,22,160,2049,rows-1}.Where(k=>k>0&&k<=rows).Distinct())for(int i=0;i<32;i++){var q=Enumerable.Range(0,5).Select(_=>random.NextDouble()*4-2).ToArray();Verify(points,q,k);cases++;}
 if(!points.Zip(snapshot).All(p=>p.First.SequenceEqual(p.Second)))throw new Exception("Input mutated");
}
foreach(int mode in new[]{0,1,2}){
 var points=Enumerable.Range(0,8193).Select(i=>Enumerable.Range(0,16).Select(j=>j>=5?i:mode==0?1d:mode==1?(i%7)*.1:j==0?i*.001:0).ToArray()).ToArray();foreach(int k in new[]{1,22,160,2049})foreach(double x in new[]{0d,.1,Math.BitIncrement(.1),1d,1e100}){Verify(points,[x,0,0,0,0],k);cases++;}
}
var concurrent=Enumerable.Range(0,12001).Select(i=>Enumerable.Range(0,16).Select(j=>j<5?random.NextDouble():i+j).ToArray()).ToArray();Parallel.For(0,64,i=>Verify(concurrent,[i*.01,.5,.2,.7,.3],160));cases+=64;
using var input=new BinaryReader(new GZipStream(File.OpenRead(args[0]),CompressionMode.Decompress));input.ReadInt32();int count=input.ReadInt32();for(int j=0;j<5;j++)input.ReadDouble();int length=input.ReadInt32();var real=Enumerable.Range(0,length).Select(_=>Enumerable.Range(0,16).Select(_=>input.ReadDouble()).ToArray()).ToArray();var queries=Enumerable.Range(0,128).Select(i=>real[i*1777%length].Take(5).Select(v=>v+.000123).ToArray()).ToArray();
var clock=Stopwatch.StartNew();ResidualNeighborLookup.Find(real,queries[0],count);double cold=clock.Elapsed.TotalMilliseconds;clock.Restart();var expected=queries.Select(q=>Reference(real,q,count).UnorderedItems.ToArray()).ToArray();double oldMs=clock.Elapsed.TotalMilliseconds;clock.Restart();for(int i=0;i<queries.Length;i++){var found=ResidualNeighborLookup.Find(real,queries[i],count).UnorderedItems.ToArray();if(!found.SequenceEqual(expected[i]))throw new Exception("Real-data heap mismatch");cases++;}double newMs=clock.Elapsed.TotalMilliseconds;
var result=new{cases,allHeapElementsAndOrderExactlyEqual=true,realRows=length,neighbors=count,queries=queries.Length,coordinateCacheColdMs=cold,referenceLookupMs=oldMs,packedLookupMs=newMs};Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(args[1]))!);File.WriteAllText(args[1],JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(result));
